script:
(function () {
  'use strict';
  // Consolidate and invest the difference: net worth with and without a consolidation loan.
  // Both paths spend the same amount every month - the larger of today's total debt payments and
  // the new loan payment - so they compare fairly. Whatever is not needed for debt that month
  // (including everything once the debt is gone) is invested at the end of the month, growing at
  // the chosen return compounded monthly (r / 12). Net worth = investments - debt still owed.
  //   Keep your debts: each debt is paid at its own fixed payment until cleared; each month
  //   interest = balance x APR / 12 (rounded to the cent) is added, then the payment.
  //   Consolidate: loan L = total debts / (1 - fee%) when the fee is added to the loan (so the fee
  //   is fee% of the loan), payment P = rL / (1 - (1 + r)^-n) rounded to the cent (L / n at 0%),
  //   last payment adjusted to clear the balance.
  // Verified (scratchpad b5debt/math.test.js):
  //   $20,000 at 10% for 5 years -> $424.94 a month (standard amortization table), 60 payments,
  //   $5,496.45 interest;
  //   $100 invested at the end of each month for 12 months at 6% = $1,233.56
  //   (100 x ((1.005^12 - 1) / 0.005)); at 0% return the investments equal the money set aside;
  //   a 3% fee on $17,700 of debt -> loan $18,247.42 and fee $547.42 (3% of the loan);
  //   with no interest anywhere and equal payoff times both paths end at the same net worth;
  //   cash check: in both paths, money put into debt + money invested = monthly outlay x months.
  var MAX_MONTHS = 1200;
  var MAX_DEBTS = 10;
  var DEFAULTS = [
    { name: 'Credit card 1', balance: 7500, apr: 24.99, pay: 225 },
    { name: 'Credit card 2', balance: 4200, apr: 21.99, pay: 130 },
    { name: 'Personal loan', balance: 6000, apr: 15.5, pay: 210 }
  ];
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var monthName = new Intl.DateTimeFormat('en-US', { month: 'short', year: 'numeric' });
  var rowCounter = 0;

  // ---- Calculation ----
  function cents(x) { return Math.round(x * 100) / 100; }

  function loanPayment(L, annualRate, n) {
    var r = annualRate / 12;
    if (r === 0) return Math.ceil(L / n * 100) / 100;
    return cents(r * L / (1 - Math.pow(1 + r, -n)));
  }

  // Monthly payment amounts and balances for the current debts until all are cleared.
  function keepSchedule(debts) {
    var bal = debts.map(function (d) { return d.balance; }), paid = [], owed = [], interest = 0;
    for (var m = 1; m <= MAX_MONTHS; m++) {
      var mp = 0, open = 0;
      for (var i = 0; i < debts.length; i++) {
        if (bal[i] <= 0.005) continue;
        var c = cents(bal[i] * debts[i].apr / 12);
        bal[i] = cents(bal[i] + c); interest += c;
        var p = Math.min(debts[i].pay, bal[i]);
        bal[i] = cents(bal[i] - p); mp += p;
        if (bal[i] > 0.005) open++; else bal[i] = 0;
      }
      paid.push(cents(mp)); owed.push(bal.reduce(function (s, b) { return s + b; }, 0));
      if (!open) return { paidOff: true, months: m, interest: interest, paid: paid, owed: owed };
    }
    return { paidOff: false, months: MAX_MONTHS, interest: interest, paid: paid, owed: owed };
  }

  function loanSchedule(L, annualRate, n) {
    var P = loanPayment(L, annualRate, n), r = annualRate / 12, bal = L, paid = [], owed = [], interest = 0;
    for (var m = 1; m <= n; m++) {
      var c = cents(bal * r);
      bal = cents(bal + c); interest += c;
      var p = m === n ? bal : Math.min(P, bal);
      bal = cents(bal - p);
      paid.push(p); owed.push(bal);
      if (bal <= 0.005) { bal = 0; owed[owed.length - 1] = 0; return { payment: P, months: m, interest: interest, paid: paid, owed: owed }; }
    }
    return { payment: P, months: n, interest: interest, paid: paid, owed: owed };
  }

  // Invest outlay minus the debt payment each month; returns year-end snapshots and the final value.
  function grow(schedule, outlay, annualReturn, horizon) {
    var i = annualReturn / 12, inv = 0, years = [], invested = 0;
    for (var m = 1; m <= horizon; m++) {
      var debtPay = m <= schedule.paid.length ? schedule.paid[m - 1] : 0;
      var add = Math.max(outlay - debtPay, 0);
      inv = inv * (1 + i) + add; invested += add;
      if (m % 12 === 0 || m === horizon) {
        var owed = m <= schedule.owed.length ? schedule.owed[m - 1] : 0;
        years.push({ month: m, owed: owed, inv: inv, net: inv - owed });
      }
    }
    return { value: inv, invested: invested, years: years };
  }

  // ---- Page ----
  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function dateAfter(months) {
    var now = new Date();
    return monthName.format(new Date(now.getFullYear(), now.getMonth() + months, 1));
  }

  function set(id, text) { document.getElementById(id).textContent = text; }

  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function addRow(body, cells) {
    var tr = document.createElement('tr');
    cells.forEach(function (text) {
      var td = document.createElement('td');
      td.textContent = text;
      tr.appendChild(td);
    });
    body.appendChild(tr);
  }

  function el(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text) e.textContent = text;
    return e;
  }

  function numberField(id, label, value, affix, affixFirst, step, max) {
    var wrap = el('div');
    var lab = el('label', 'form-label', label);
    lab.setAttribute('for', id);
    var group = el('div', 'input-group');
    var input = el('input', 'min-w-0 flex-1 bg-transparent px-3 text-[15px] tabular-nums text-ink focus:outline-none');
    input.type = 'number'; input.id = id; input.min = '0'; input.step = step; input.inputMode = 'decimal';
    if (max) input.max = max;
    input.value = value === '' ? '' : String(value);
    var a = el('span', 'input-affix', affix);
    if (affixFirst) { group.appendChild(a); group.appendChild(input); } else { group.appendChild(input); group.appendChild(a); }
    wrap.appendChild(lab); wrap.appendChild(group);
    return wrap;
  }

  function addDebtRow(d) {
    var list = document.getElementById('cliDebts');
    rowCounter++;
    var n = rowCounter;
    var row = el('div', 'space-y-3 rounded-xl border border-line p-4');
    row.setAttribute('data-debt-row', String(n));
    var head = el('div', 'flex flex-wrap items-center justify-between gap-2');
    var title = el('p', 'text-sm font-semibold text-ink', 'Debt');
    title.setAttribute('data-debt-title', '');
    var remove = el('button', 'button-secondary h-9 px-3 text-sm', 'Remove');
    remove.type = 'button';
    remove.setAttribute('data-remove', '');
    remove.addEventListener('click', function () {
      if (list.querySelectorAll('[data-debt-row]').length <= 1) return;
      row.remove();
      refreshRows(); update();
    });
    head.appendChild(title); head.appendChild(remove);
    row.appendChild(head);

    var nameWrap = el('div');
    var nameLabel = el('label', 'form-label', 'Name');
    nameLabel.setAttribute('for', 'cliName' + n);
    var name = el('input', 'form-control');
    name.type = 'text'; name.id = 'cliName' + n; name.maxLength = 40; name.autocomplete = 'off';
    name.placeholder = 'e.g. Visa card';
    name.value = d.name || '';
    nameWrap.appendChild(nameLabel); nameWrap.appendChild(name);
    row.appendChild(nameWrap);

    var pair = el('div', 'form-row form-row-2');
    pair.appendChild(numberField('cliBal' + n, 'Balance', d.balance, '$', true, '100'));
    pair.appendChild(numberField('cliApr' + n, 'APR', d.apr, '%', false, '0.1', '100'));
    row.appendChild(pair);
    row.appendChild(numberField('cliPay' + n, 'Monthly payment', d.pay, '$', true, '10'));
    list.appendChild(row);
    refreshRows();
  }

  function refreshRows() {
    var rows = document.getElementById('cliDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      row.querySelector('[data-debt-title]').textContent = 'Debt ' + (i + 1);
      var rm = row.querySelector('[data-remove]');
      rm.disabled = rows.length <= 1;
      rm.setAttribute('aria-label', 'Remove debt ' + (i + 1));
    });
    document.getElementById('cliAdd').disabled = rows.length >= MAX_DEBTS;
  }

  function readDebts() {
    var out = [], ok = true;
    var rows = document.getElementById('cliDebts').querySelectorAll('[data-debt-row]');
    rows.forEach(function (row, i) {
      var n = row.getAttribute('data-debt-row');
      var name = document.getElementById('cliName' + n).value.trim() || ('Debt ' + (i + 1));
      var balEl = document.getElementById('cliBal' + n), aprEl = document.getElementById('cliApr' + n), payEl = document.getElementById('cliPay' + n);
      var bal = parseFloat(balEl.value), apr = aprEl.value.trim() === '' ? 0 : parseFloat(aprEl.value), pay = parseFloat(payEl.value);
      if (balEl.value.trim() === '' || bal === 0) {
        [balEl, aprEl, payEl].forEach(function (e) { e.setAttribute('aria-invalid', 'false'); });
        return;
      }
      var badBal = isNaN(bal) || bal < 0 || bal > 1e8, badApr = isNaN(apr) || apr < 0 || apr > 100, badPay = isNaN(pay) || pay <= 0;
      balEl.setAttribute('aria-invalid', String(badBal));
      aprEl.setAttribute('aria-invalid', String(badApr));
      payEl.setAttribute('aria-invalid', String(badPay));
      if (badBal || badApr || badPay) { ok = false; return; }
      out.push({ name: name, balance: bal, apr: apr / 100, pay: pay });
    });
    return { ok: ok, debts: out };
  }

  function clearResults() {
    ['cliNetCons', 'cliNetKeep', 'cliDiff', 'cliCurrent', 'cliLoanPay', 'cliSavings', 'cliLoanAmt', 'cliKeepInt', 'cliLoanInt'].forEach(function (id) { set(id, '–'); });
    ['cliDiffNote', 'cliOutlayNote', 'cliLoanAmtNote', 'cliKeepIntNote', 'cliLoanIntNote', 'cliSavingsNote'].forEach(function (id) { set(id, ''); });
    document.getElementById('cliWarn').hidden = true;
    clearBody('cliYears');
  }

  function update() {
    var error = document.getElementById('cliError');
    var v = function (id) { var e = document.getElementById(id); return e.value.trim() === '' ? NaN : parseFloat(e.value); };
    var rate = v('cliRate'), years = v('cliTerm'), feeEl = document.getElementById('cliFee');
    var fee = feeEl.value.trim() === '' ? 0 : parseFloat(feeEl.value);
    var ret = v('cliReturn'), horizonYears = Math.round(v('cliHorizon'));
    var input = readDebts();
    var problem = '';
    if (!input.ok) problem = 'Check the highlighted debts: balances of $0 or more, APRs from 0 to 100% and monthly payments above $0.';
    else if (!input.debts.length) problem = 'Enter at least one debt with a balance above $0.';
    else if (isNaN(rate) || rate < 0 || rate > 100) problem = 'Enter a loan rate from 0 to 100%.';
    else if (isNaN(years) || years < 1 || years > 30) problem = 'Enter a loan term of 1 to 30 years.';
    else if (isNaN(fee) || fee < 0 || fee >= 20) problem = 'Enter a loan fee from 0 to under 20%.';
    else if (isNaN(ret) || ret < 0 || ret > 30) problem = 'Enter an investment return from 0 to 30%.';
    else if (isNaN(horizonYears) || horizonYears < 1 || horizonYears > 40) problem = 'Enter a comparison period of 1 to 40 years.';
    var debts = input.debts, keep;
    if (!problem) {
      keep = keepSchedule(debts);
      if (!keep.paidOff) {
        for (var k = 0; k < debts.length; k++) {
          if (debts[k].pay <= cents(debts[k].balance * debts[k].apr / 12)) { problem = 'The payment on ' + debts[k].name + ' does not cover its interest, so it is never paid off. Raise that payment.'; break; }
        }
        if (!problem) problem = 'These payments do not clear your debts within 100 years. Raise the payments.';
      }
    }
    if (problem) { error.hidden = false; error.textContent = problem; clearResults(); return; }
    error.hidden = true; error.textContent = '';

    var total = debts.reduce(function (s, d) { return s + d.balance; }, 0);
    var current = debts.reduce(function (s, d) { return s + d.pay; }, 0);
    var L = cents(total / (1 - fee / 100)), n = Math.round(years * 12);
    var loan = loanSchedule(L, rate / 100, n);
    var outlay = Math.max(current, loan.payment), horizon = horizonYears * 12;
    var gKeep = grow(keep, outlay, ret / 100, horizon), gCons = grow(loan, outlay, ret / 100, horizon);
    var netKeep = gKeep.years[gKeep.years.length - 1].net, netCons = gCons.years[gCons.years.length - 1].net;

    set('cliCurrent', money.format(current));
    set('cliLoanPay', money.format(loan.payment));
    set('cliSavings', money.format(Math.abs(current - loan.payment)));
    set('cliSavingsNote', current >= loan.payment ? 'Less each month with the loan. This is what gets invested.' : 'The loan payment is higher, so keeping your debts frees this much to invest.');
    set('cliLoanAmt', money.format(L));
    set('cliLoanAmtNote', fee > 0 ? 'Includes a ' + money.format(L - total) + ' fee.' : 'No fee.');
    set('cliKeepInt', money.format(keep.interest));
    set('cliKeepIntNote', 'Debt-free ' + dateAfter(keep.months) + '.');
    set('cliLoanInt', money.format(loan.interest));
    set('cliLoanIntNote', 'Debt-free ' + dateAfter(loan.months) + '.');
    set('cliNetCons', money.format(netCons));
    set('cliNetKeep', money.format(netKeep));
    var diff = netCons - netKeep;
    set('cliDiff', money.format(Math.abs(diff)));
    set('cliDiffNote', Math.abs(diff) < 0.5 ? 'Both paths end level after ' + horizonYears + (horizonYears === 1 ? ' year.' : ' years.') :
      (diff > 0 ? 'More with the consolidation loan' : 'More by keeping your current debts') + ' after ' + horizonYears + (horizonYears === 1 ? ' year.' : ' years.'));
    var warn = document.getElementById('cliWarn');
    warn.hidden = horizon >= Math.max(keep.months, loan.months);
    if (!warn.hidden) warn.textContent = 'Some debt is still owed at the end of ' + horizonYears + (horizonYears === 1 ? ' year' : ' years') + '. Net worth subtracts it, but a longer comparison period shows the full picture.';
    set('cliOutlayNote', 'Both paths put ' + money.format(outlay) + ' a month toward debt and investing.');

    var body = clearBody('cliYears');
    gKeep.years.forEach(function (a, idx) {
      var b = gCons.years[idx];
      addRow(body, [String(Math.ceil(a.month / 12)), money.format(a.owed), money.format(a.inv), money.format(a.net),
        money.format(b.owed), money.format(b.inv), money.format(b.net)]);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    DEFAULTS.forEach(addDebtRow);
    var form = document.getElementById('cliForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    document.getElementById('cliAdd').addEventListener('click', function () {
      if (document.getElementById('cliDebts').querySelectorAll('[data-debt-row]').length >= MAX_DEBTS) return;
      addDebtRow({ name: '', balance: '', apr: '', pay: '' });
      update();
    });
    update();
  });
})();
